const COMMON = "You are an implementer on round 5 of the JevCode interactive TUI (repo " + REPO + " — a git WORKTREE on branch r5-impl; node_modules and .env are symlinks into the main checkout at /Users/prateekjannu/Documents/vscode/JevCode, which you NEVER touch; never git stash, commit, stage, switch branch, merge or rebase). TypeScript strict, no any (node scripts/no-any.mjs must stay green); ESM; Node 22; runtime deps ONLY ink 7.1.1 + react 19.3.0. The specification is " + DESIGN + " — read §0 (D-AC…D-AT with §0.1 ratification, §0.2 amendments, §0.3 owner amendments — all binding), §1, your own sections, §7 (the numbered edge matrix — every row that names your surface), §8 (contract 1.8: additive TUI-block types only; §8.2 REQUESTS to the harness are NOT yours to implement — code against fixtures/stubs per §8.4 where a request has not landed), §9 (module map: §9.1 is the single source of truth for which files you may edit; §9.2 shared-file rows; §9.3 waves and ordering constraints), §10 (your tests), §11 (gates), §12 (strings — verbatim, with --plain / --ascii / screen-reader twins), §13 (twins and the pin inventory), §15.1/§15.2 (the harness session's binding answers and the landed W2b names — e.g. the consumer type is LedgerHandle with NO alias, `claims` not `leases`, secretId() for import question ids, meter.heldUsd?.() is optional, read ledger.fold on mount). Predecessors: docs/TUI-DESIGN-4.md (round 4 is MERGED on this tree — import the real src/tui/{block/lines,fit,gutter}.ts; the §8.4 stub table is a contingency you will not need), docs/TUI-DESIGN-3.md, docs/TUI-DESIGN-2.md, docs/TUI-DESIGN.md; the digest docs/research/tui/round-5/00-contract-digest.md (§A–§G) and the six research files beside it. Today is " + DATE + ". Every existing gate stays (first frame < 300 ms with zero network and nothing from the provider registry / model catalogue on the argv path; zero clears outside shrink segments; composer keystroke → frame p95 < 16 ms via Ink's immediate path (UiState.keySeq); transcript.log / --plain / TUI identity through the one formatter src/tui/plain.ts; keys never printed or logged; no auto-approve; reduced motion, screen reader, --plain, --ascii, NO_COLOR, SSH fps 15, the flat tier and minsize keep working; every new row has a §12 string, a --plain twin and a test). OWNERSHIP: edit ONLY the files in your §9.1 cell; for any other file write the exact hunk in your report under requests — src/synth/**, src/bench/**, src/jev/**, src/loop/**, src/coordination/**, src/orchestrate/**, src/import/**, src/models/**, src/provider/**, src/spend/**, src/checkpoint/**, src/errors.ts and src/core/types.ts's non-TUI blocks are the harness session's and READ-ONLY (import from them freely; src/orchestrate/index.js is a VALUE module reaching node:fs — `import type` only from it). Other slots edit concurrently in this worktree: expect their files to change under you and never edit them. Verification before you report: npx tsc -p tsconfig.json --noEmit (filter to your files if others are mid-edit and say so), node scripts/no-any.mjs, npx vitest run --project unit <your test files>, then the whole unit suite once (list failures in files you do not own); do not run npm run build, jevcode perf or pty suites unless your brief says so. The machine is shared with a peer session's bounded test runs: timing tests may flake under load — re-run alone before calling something a defect. Your final message is data for the orchestrator: files changed, tests with pass counts, measured numbers, deviations from the design (with the reason), requests to other slots or the harness (exact hunks), problems."
const IMPL_SCHEMA = { type: "object", properties: { files: { type: "array", items: { type: "string" } }, tests: { type: "string" }, measured: { type: "array", items: { type: "string" } }, deviations: { type: "array", items: { type: "string" } }, requests: { type: "array", items: { type: "string" } }, problems: { type: "array", items: { type: "string" } }, tscClean: { type: "boolean" }, testsPass: { type: "boolean" } }, required: ["files", "tests", "deviations", "requests", "problems", "tscClean", "testsPass"] }
const REVIEW_SCHEMA = { type: "object", properties: { findings: { type: "array", items: { type: "object", properties: { severity: { type: "string", enum: ["blocker", "major", "minor"] }, file: { type: "string" }, problem: { type: "string" }, evidence: { type: "string" }, fix: { type: "string" } }, required: ["severity", "file", "problem", "evidence", "fix"] } }, missingTests: { type: "array", items: { type: "string" } } }, required: ["findings", "missingTests"] }
const SLOTS = EMBEDDED.slots

phase("Implement")
const w0 = await agent(COMMON + "\n\nWAVE 0 (§8.1 contract 1.8, §9.3 W−1 + W0 folded: this worktree IS main at its fork, so no rebase — but every file:line in the design was read on r5-design and several are stale against main by construction). You are the contract pass and the re-verifier. (1) Re-read the built / not-built tables of §2.0, §3.0, §4.1, §5.0 and §6.0 and every file:line in §8.2 against THIS tree; write the diff as docs/research/tui/round-5/w0-reverify.md (what moved, what already landed — contract 1.5/1.6, W2b names, meter.heldUsd?, the decompose/coordinate stage tables, the BlockingKind members with placeholder cases, round 4's block/fit/gutter — and what is still missing with its §8.2 request number). (2) Apply EXACTLY §8.1 items 1–6 as additive types in a `// contract 1.8` block in src/core/types.ts placed AFTER `// contract 1.7` (never reorder or edit any other block), the SessionActivityView and SelfIdentityView interfaces, the eight `contract 1.6 item N (TUI-DESIGN-4 …)` comment renumberings to `contract 1.7 item N` (§8.1 item 10), and the two `[session]` two-line edits in test/unit/tui/theme.test.ts and test/unit/tui/theme-palette.test.ts (§8.1 item 2). (3) Nothing else lands in W0. tsc --strict green, every fake compiles, node scripts/no-any.mjs ok, test/unit/core + test/unit/tui/theme*.test.ts green. Report files, the re-verify diff summary, and any design line that is wrong on this tree.", Object.assign({ label: "w0:contract-1.8", phase: "Implement", schema: IMPL_SCHEMA }, M))
log("W0 done: tsc=" + (w0 && w0.tscClean) + " tests=" + (w0 && w0.testsPass))

const results = await pipeline(
  SLOTS,
  (s) => agent(COMMON + "\n\nW0 REPORT (contract 1.8 is on the tree; read docs/research/tui/round-5/w0-reverify.md first): " + JSON.stringify(w0 || {}).slice(0, 6000) + "\n\nSLOT BRIEF:\n" + s.brief + "\n\nSHARED TESTS THE INTEGRATOR LANDS (know their expectations): " + EMBEDDED.sharedTests, Object.assign({ label: "impl:" + s.key, phase: "Implement", schema: IMPL_SCHEMA }, M)).then((r) => (r ? Object.assign({}, r, { key: s.key }) : null)),
  (impl, s) => {
    if (!impl) return null
    return agent("You are an ADVERSARIAL REVIEWER for slot " + s.key + " of round 5 (repo " + REPO + ", a git worktree on branch r5-impl — never touch the main checkout; spec " + DESIGN + ", today " + DATE + "). Files reported: " + impl.files.join(", ") + ". Read the slot brief, the design sections it names, §7 rows for its surface, §12 (strings), §13 (twins), §15.1/§15.2, then every listed file and its tests; run npx tsc -p tsconfig.json --noEmit 2>&1 | grep -E \"" + s.grep + "\" and the slot's tests; try to break it: a string differing from §12, a missing --plain/--ascii/SR twin, a row wider than the terminal at 40 columns, a first-frame/argv-path import of the provider registry or model catalogue or any node:fs module in a pure builder, a key byte reaching a frame or a log, an omitted row when the fold degrades, a path or pid in /peers or /who output, a wrong consumer type (Ledger instead of LedgerHandle), `leases` instead of `claims`, a secret id derived by counting, a `meter.heldUsd()` call without the optional-call form, an Enter that approves a confirm, files edited outside the slot's §9.1 cell (git status), a shared-file edit that §9.2 assigns to another owner, missing tests from §10. Return up to 25 findings with evidence and fixes and the list of missing tests. Do not modify files.\n\nSLOT BRIEF:\n" + s.brief + "\n\nIMPLEMENTER REPORT: deviations=" + JSON.stringify(impl.deviations) + " problems=" + JSON.stringify(impl.problems) + " requests=" + JSON.stringify(impl.requests) + " measured=" + JSON.stringify(impl.measured || []), Object.assign({ label: "review:" + s.key, phase: "Review", schema: REVIEW_SCHEMA }, M)).then((rv) => ({ impl: impl, review: rv }))
  },
  (pair, s) => {
    if (!pair || !pair.review) return pair
    const text = pair.review.findings.map((f, i) => (i + 1) + ". [" + f.severity + "] " + f.file + ": " + f.problem + " — evidence: " + f.evidence + " — fix: " + f.fix).join("\n")
    return agent(COMMON + "\n\nYou are the implementer of slot " + s.key + " again (FIX pass; your files: " + pair.impl.files.join(", ") + "). Apply every blocker and major finding, the minors unless they contradict the design, add the missing tests, re-run the verification (tsc, no-any, your tests, then the whole unit suite once). Also land any REQUEST addressed to your slot that other slots have posted in files you own (ask nothing; the design says who owns what). FINDINGS:\n" + text + "\nMISSING TESTS:\n" + pair.review.missingTests.join("\n") + "\n\nSLOT BRIEF:\n" + s.brief, Object.assign({ label: "fix:" + s.key, phase: "Fix", schema: IMPL_SCHEMA }, M)).then((fixed) => Object.assign({}, pair, { fixed: fixed }))
  },
)
const slotReports = results.filter(Boolean).map((r) => ({ key: r.impl.key, files: (r.fixed || r.impl).files, requests: (r.fixed || r.impl).requests, problems: (r.fixed || r.impl).problems, deviations: (r.fixed || r.impl).deviations, findings: r.review ? r.review.findings.length : 0 }))
log("slots done: " + slotReports.map((r) => r.key + "(" + r.findings + ")").join(", "))

phase("Integrate")
const integ = await agent("You are the INTEGRATOR for round 5 (repo " + REPO + " — a git worktree on branch r5-impl; node_modules and .env are symlinks into the main checkout at /Users/prateekjannu/Documents/vscode/JevCode, which you never touch; never switch branch, merge, rebase, stash or commit — the owner merges when you report green; spec " + DESIGN + ", today " + DATE + "). All slots are on disk; their reports: " + JSON.stringify(slotReports).slice(0, 30000) + "\n\nFIRST land every open cross-slot REQUEST in the §9.2 owner files in §9.3's W3 → W4 order (the shared React shell as one edit; status/lines.ts as one edit; then config/{types,defaults,validate,resolve}.ts → cli/args.ts + cli/main.tsx → commands/registry.ts → cli/session.ts → session/index.ts LAST), minimal and design-cited; requests addressed to the HARNESS session (§8.2 R-numbers, or any edit in src/loop/**, src/synth/**, src/coordination/**, src/orchestrate/**, src/import/**, src/models/**, src/provider/**, src/spend/**, src/checkpoint/**, src/errors.ts or a non-TUI block of src/core/types.ts) are NOT landed: if a slot edited such a file, revert it from the tree and write the exact hunk into docs/research/tui/round-5/harness-session-hunks.patch and your report. Then land W5's shared tests (§10 \"Shared\": registry.test.ts count/no-dead-pointer, contract.test.ts header order 1.1, 1.2, 1.2, 1.3, 1.4, 1.5, 1.6, 1.7, 1.8 and the settings lint G-R5-8, r5-identity.test.ts) and the new pty .steps files with assertNoKeyBytes in every one. Then run in order and report every number: npx tsc -p tsconfig.json --noEmit; node scripts/no-any.mjs; npx vitest run --project unit --maxWorkers=3 (ALL must pass — re-run timing flakes alone; fix real regressions); node scripts/gen-docs.mjs then --check (the generator must know the new command categories and the agents KeyContext); npm run build; node scripts/check-pack.mjs; env -u CI npx vitest run --project pty; env -u CI sh test/pty/run-smoke.sh; then node bin/jevcode.js perf when the machine is quiet (check uptime; if 1-minute load > 8 wait up to 20 min, then run and record the load; the §11 gates incl. G-R5-1…G-R5-10 must pass or be named red with numbers). Then drive the real product with scripts/pty/drive.exp (read docs/research/tui/20-pty-driver-findings.md first), --mock, hermetic, per new surface: /who with fixtures, /pause /end with the confirm, /context and /compact, the agents tab with fixtures (hidden without delegation), the import overlay through resize 24x80 → 12x60 → 40x120, the model picker at 120x40 then resize 40 24 and --ascii — zero clears outside shrink, no ESC[3J, no frame taller than rows, 0 key bytes. Then LIVE, paid once, from the repo root with its .env (env -u ANTHROPIC_API_KEY; JEV_API_KEY unset; a temp JEVCODE_HOME; a fresh demo-py copy — see docs/live/tui/round-4/run-live.sh and write docs/live/tui/round-5/run-live.sh the same way): node bin/jevcode.js --workspace <ws> --spend-cap 0.30 under the llm-jev default at 24x80: hero, hi, /who, /context, a task, /jev, /exit; and one `jevcode models search glm` and one `jevcode import --plan` against a fixture home; save captures under docs/live/tui/round-5/ with a README table; assert 0 key bytes. Write docs/STATUS.md \"Round 5\" (what was built per slot, every gate with numbers, deviations, not verified, hunks for the harness) and the CHANGELOG 0.6.0 entry (package.json bump is the owner's), docs/TUI.md / docs/COMMANDS.md / docs/KEYS.md / docs/IMPORT.md and README rows per §9.2's docs row, and the docs/DECISIONS.md entries §12/§13 name. Do not commit.", Object.assign({ label: "integrate:round-5", phase: "Integrate" }, M))
return { w0: w0, slots: slotReports, integration: integ }
